mapper.select:
SELECT ETR_ENTRUST.ENTRUST_ID as closeId, ETR_ENTRUST.ps as ps, ETR_ENTRUST.finprod_type2 as finprodType2, ETR_ENTRUST.TRADE_MARKET tradeMarket, nvl(ETR_ENTRUST_ADD.BUSI_TYPE_POSITION ,btm.OUTPUT_VALUE_1) busiTypePosition, ISSUE.ISSUE_CLASS issueClass FROM ETR_ENTRUST LEFT JOIN ETR_ENTRUST_ADD ON ETR_ENTRUST_ADD.ENTRUST_ID = ETR_ENTRUST.ENTRUST_ID LEFT JOIN FIN_PRODUCT_TYPE_CONFIG btm ON ( ETR_ENTRUST.FINPROD_TYPE2 = btm.INPUT_VALUE_2 OR btm.INPUT_VALUE_2 IS NULL) AND ( ETR_ENTRUST.PS = btm.INPUT_VALUE_3 OR btm.INPUT_VALUE_3 IS NULL) AND ( ETR_ENTRUST.TRADE_PLAT = btm.INPUT_VALUE_1 OR btm.INPUT_VALUE_1 IS NULL) LEFT JOIN FIN_PRODUCT_ISSUE ISSUE ON ETR_ENTRUST.FINPROD_ID = ISSUE.FINPROD_ID WHERE ETR_ENTRUST.PS != #{PS_T03} AND nvl(ETR_ENTRUST_ADD.BUSI_TYPE_POSITION ,btm.OUTPUT_VALUE_1) NOT IN ('01') AND ETR_ENTRUST.ENTRUST_ID IN ( SELECT ENTRUST_ID FROM ETR_ENTRUST WHERE ENTRUST_STATUS IN ( #{ENTRUST_STATUS_01}, #{ENTRUST_STATUS_02}, #{ENTRUST_STATUS_03}, #{ENTRUST_STATUS_05},#{ENTRUST_STATUS_08},#{ENTRUST_STATUS_07} )
AND ETR_ENTRUST.MDATE <= TO_DATE(#{sysDate},'YYYY-MM-DD')
) UNION ALL SELECT EE.ENTRUST_ID as closeId, EE.ps as ps, EE.finprod_type2 as finprodType2, EE.TRADE_MARKET tradeMarket, nvl(ETR_ENTRUST_ADD.BUSI_TYPE_POSITION ,btm.OUTPUT_VALUE_1) busiTypePosition, ISSUE.ISSUE_CLASS issueClass FROM ETR_ENTRUST EE LEFT JOIN ETR_ENTRUST_ADD ON ETR_ENTRUST_ADD.ENTRUST_ID = EE.ENTRUST_ID LEFT JOIN FIN_PRODUCT_TYPE_CONFIG btm ON ( EE.FINPROD_TYPE2 = btm.INPUT_VALUE_2 OR btm.INPUT_VALUE_2 IS NULL) AND ( EE.PS = btm.INPUT_VALUE_3 OR btm.INPUT_VALUE_3 IS NULL) AND ( EE.TRADE_PLAT = btm.INPUT_VALUE_1 OR btm.INPUT_VALUE_1 IS NULL) LEFT JOIN FIN_PRODUCT_ISSUE ISSUE ON EE.FINPROD_ID = ISSUE.FINPROD_ID WHERE EE.PS = 'T03' AND EE.ENTRUST_ID IN ( SELECT ENTRUST_ID FROM ETR_ENTRUST WHERE ENTRUST_STATUS IN ( #{ENTRUST_STATUS_01}, #{ENTRUST_STATUS_02}, #{ENTRUST_STATUS_03}, #{ENTRUST_STATUS_05},#{ENTRUST_STATUS_08},#{ENTRUST_STATUS_07} )
AND EE.MDATE <= TO_DATE(#{sysDate},'YYYY-MM-DD')
) AND EXISTS ( SELECT RFPD.ENTRUST_ID FROM REG_FIN_PRODUCT_DEAL RFPD INNER JOIN FIN_EXERCISE_PLAN FEP ON RFPD.FINPROD_ID = FEP.FINPROD_ID AND RFPD.FINPROD_TYPE2 = #{FINPROD_TYPE2_F01} AND RFPD.PS = #{PS_T03} AND RFPD.TRADE_DATE > FEP.VDATE
AND FEP.EXERCISE_DATE = TO_DATE(#{sysDate},'YYYY-MM-DD') +1
WHERE EE.ENTRUST_ID = RFPD.ENTRUST_ID) UNION ALL SELECT ETR_ENTRUST.ENTRUST_ID as closeId, ETR_ENTRUST.ps as ps, ETR_ENTRUST.finprod_type2 as finprodType2, ETR_ENTRUST.TRADE_MARKET tradeMarket, nvl(ETR_ENTRUST_ADD.BUSI_TYPE_POSITION ,btm.OUTPUT_VALUE_1) busiTypePosition, ISSUE.ISSUE_CLASS issueClass FROM ETR_ENTRUST LEFT JOIN ETR_ENTRUST_ADD ON ETR_ENTRUST_ADD.ENTRUST_ID = ETR_ENTRUST.ENTRUST_ID LEFT JOIN FIN_PRODUCT_TYPE_CONFIG btm ON ( ETR_ENTRUST.FINPROD_TYPE2 = btm.INPUT_VALUE_2 OR btm.INPUT_VALUE_2 IS NULL) AND ( ETR_ENTRUST.PS = btm.INPUT_VALUE_3 OR btm.INPUT_VALUE_3 IS NULL) AND ( ETR_ENTRUST.TRADE_PLAT = btm.INPUT_VALUE_1 OR btm.INPUT_VALUE_1 IS NULL) LEFT JOIN ( SELECT CASE WHEN fpi.ISSUE_CLASS = '01' THEN NULL WHEN (bobrt.BID_MODLE IS NOT NULL AND bobrt.BID_MODLE = '03') OR bobrt.IS_WIN = 'Y' THEN '04' WHEN bobrt.BID_MODLE IS NULL THEN '01' WHEN bobrt.IS_WIN = 'N' THEN '03' WHEN (bobrt.BID_MODLE IN ('01', '02') AND bobrt.IS_WIN IS NULL) THEN '02' ELSE '05' END AS firstBidStatus, ee.ENTRUST_ID entrustId FROM ETR_ENTRUST ee LEFT JOIN FIN_PRODUCT fp ON fp.FINPROD_ID = ee.FINPROD_ID LEFT JOIN FIN_PRODUCT_ISSUE fpi ON fpi.FINPROD_ID = fp.FINPROD_ID LEFT JOIN ( SELECT bo.BID_MODLE, brt.IS_WIN ,bo.FINPROD_ID,bobp.ENTRUST_ID FROM BID_ORDER bo LEFT JOIN BID_ORDER_BID_PRICE bobp ON bobp.BID_ID = bo.BID_ID LEFT JOIN BID_RESULT_TOTAL brt ON brt.BID_ID = bo.BID_ID AND brt.STATUS = '01' AND brt.FINPROD_ID = bo.FINPROD_ID WHERE bo.IS_CANCEL = 'N' AND bo.TRADE_STATUS = '01' GROUP BY bo.BID_MODLE, brt.IS_WIN, bo.FINPROD_ID,bobp.ENTRUST_ID ) bobrt ON bobrt.FINPROD_ID = fp.FINPROD_ID AND bobrt.ENTRUST_ID = ee.ENTRUST_ID ) firstBid ON firstBid.entrustId = ETR_ENTRUST.ENTRUST_ID
LEFT JOIN FIN_PRODUCT_ISSUE ISSUE ON ETR_ENTRUST.FINPROD_ID = ISSUE.FINPROD_ID WHERE ETR_ENTRUST.PS != #{PS_T03} AND nvl(ETR_ENTRUST_ADD.BUSI_TYPE_POSITION ,btm.OUTPUT_VALUE_1) = '01' AND firstBid.firstBidStatus = '01' AND ETR_ENTRUST.ENTRUST_ID IN ( SELECT ENTRUST_ID FROM ETR_ENTRUST WHERE ENTRUST_STATUS IN ( #{ENTRUST_STATUS_01}, #{ENTRUST_STATUS_02}, #{ENTRUST_STATUS_03}, #{ENTRUST_STATUS_05},#{ENTRUST_STATUS_08},#{ENTRUST_STATUS_07} )
AND ETR_ENTRUST.MDATE <= TO_DATE(#{sysDate},'YYYY-MM-DD')
)

